/** One placement, and the environment a worker claiming it has to satisfy. */
export interface PlacementManifest {
  /** The name a worker claims at join (`docs/distributed.md` §3.1). */
  readonly name: string;
  /**
   * `members:`, in the order the deploy file writes them (grammar §14.1).
   *
   * For a **reader**, not for a caller: the scheduler queues work to a placement
   * by name and never consults this list (`docs/distributed.md` §2), and the
   * `environment` beside it is already the answer to what a worker must satisfy.
   * It is here because a worker holds no YAML — the artifact is the only thing
   * it is served — so "what did I just claim" is otherwise unanswerable on the
   * machine that claimed it.
   */
  readonly members: readonly string[];
  /**
   * The variables of every component that can execute in this placement's
   * process, sorted by name — `docs/distributed.md` §9.1's partition.
   *
   * Names only. A manifest carries no value and no site: what a join reports is
   * a subset of this list (§9.2), and a report scoped to anything wider would be
   * telling the hub about credentials that are none of its business.
   */
  readonly environment: readonly string[];
}

/**
 * The identity a delivery this deployment makes carries (grammar §13.3).
 *
 * The **outbound** block, and the deploy layer's own copy of it: `trace_sink:`
 * reuses grammar §13.3's shape rather than inventing one beside it, so a
 * collector written against a trigger's `callback_auth:` verifies a trace export
 * unchanged. `./triggers.ts`'s `CallbackAuth` is the same shape under the name
 * the trigger surface gives it, and satisfies this type structurally — which is
 * what lets `./delivery.ts` sign both kinds of delivery with one function.
 *
 * Never a credential: the **variable name** holding one, resolved by the process
 * that spends it (grammar §4.3).
 */
export interface OutboundAuth {
  readonly bearer?: {
    readonly header: string;
    readonly prefix: string;
    readonly tokenEnv: string;
  };
  readonly hmac?: { readonly secretEnv: string };
}

/**
 * Which backend an execution journal lives on (grammar §14.7, PRD resolved q62).
 *
 * A closed set of three, and the runtime never widens it: `./journal.ts` looks
 * the provider up in the arms `build` emitted, and a provider with no arm is a
 * project that was not built from this deploy layer rather than a deployment's
 * mistake.
 */
export type JournalProvider = "sqlite" | "postgres" | "mysql";

/**
 * What this target said about its journal (grammar §14.7).
 *
 * A target that declared no `journal:` block carries `provider: "sqlite"` here
 * and no variable: the default is *stated* in the artifact rather than left for
 * a reader to infer, so "where does this project's journal live" is answerable
 * from the emitted bytes under every target.
 *
 * Never a credential: the **variable name** holding the address, resolved by the
 * process that dials it (grammar §4.3), which on a mesh is the hub and only the
 * hub — PRD resolved q42 makes it the single writer, so no worker's manifest
 * carries this one (`docs/distributed.md` §9.1).
 */
export interface JournalBinding {
  readonly provider: JournalProvider;
  /**
   * The variable holding the connection, on a provider that dials out.
   *
   * Absent on `sqlite`, which opens a file beside the project's stores and has
   * no address at all.
   */
  readonly urlEnv?: string;
}

/** `trace_sink:` — where every settled execution's trace goes (grammar §14.5). */
export interface TraceSink {
  /** The absolute address it is POSTed to. */
  readonly url: string;
  /**
   * What the body is, with grammar §14.5's default already applied.
   *
   * `envelope` is the trace document itself (`docs/trace.md` §2); `otlp` is the
   * OTLP/JSON `ExportTraceServiceRequest` `./otlp.ts` maps it to (§12).
   */
  readonly format: "envelope" | "otlp";
  /** How a delivery identifies itself, absent where the collector wants nothing. */
  readonly auth?: OutboundAuth;
}

